"""What both renderers share: the generated file, values in a case ({{unique}}, {{pnr}}, {{row.amount}}),
test names, and the Jinja2 templates."""

import re
from dataclasses import dataclass, field
from typing import Union

from jinja2 import Environment, PackageLoader, StrictUndefined

from qa_agent.cases import Case

VALUE = re.compile(r"\{\{\s*([^{}]+?)\s*\}\}")
HEADER = "Generated by qa-agent from {source}. Do not edit: change the cases, then run qa-agent generate."
BUILT_IN_MARKERS = ("smoke", "regression", "functional", "writes")
NAME_WORDS = 10


class RenderError(Exception):
    """A case can't be written in this framework (the reason says why and what to change)."""


@dataclass(frozen=True)
class GeneratedFile:
    path: str               # relative to the project: tests/generated/test_bookings.py
    text: str


@dataclass(frozen=True)
class Literal:
    text: str


@dataclass(frozen=True)
class Value:
    kind: str               # "unique", "captured" or "row"
    name: str = ""


Part = Union[Literal, Value]


@dataclass
class Uses:
    """What a test needs at its top: a unique id, a data row, another service's client."""
    unique: bool = False
    row: bool = False
    services: set = field(default_factory=set)


def parts(text: str, uses: Uses) -> list[Part]:
    """'Asha {{unique}}' -> [Literal('Asha '), Value('unique')]."""
    found, position = [], 0
    for match in VALUE.finditer(text):
        if match.start() > position:
            found.append(Literal(text[position:match.start()]))
        name = match.group(1)
        if name == "unique":
            uses.unique = True
            found.append(Value("unique"))
        elif name.startswith("row."):
            uses.row = True
            found.append(Value("row", name[4:]))
        else:
            found.append(Value("captured", name))
        position = match.end()
    if position < len(text):
        found.append(Literal(text[position:]))
    return found


def title_words(case: Case) -> list[str]:
    words = re.findall(r"[a-z0-9]+", case.title.lower().replace("'", "").replace("’", ""))
    return words[:NAME_WORDS] or ["case"]


def id_slug(case: Case) -> str:
    return re.sub(r"[^a-z0-9]+", "_", case.id.lower()).strip("_")


def file_slug(stem: str) -> str:
    return re.sub(r"[^a-z0-9]+", "_", stem.lower()).strip("_") or "cases"


def is_write(case: Case) -> bool:
    return any(step.request.method != "GET" for step in case.steps)


def groups(case: Case) -> list[str]:
    """The suite, the team's tags, and 'writes' for a case that changes data (skipped on a read-only
    environment)."""
    found = [case.suite] + [tag for tag in case.tags if tag != case.suite]
    if is_write(case) and "writes" not in found:
        found.append("writes")
    return found


TEMPLATES = Environment(loader=PackageLoader("qa_agent.renderers", "templates"), undefined=StrictUndefined,
                        keep_trailing_newline=True, trim_blocks=True, lstrip_blocks=True)
